// Coordenadas base por ciudad para mapear los 119 grupos en Google Maps
function getCityCoords(city: string, address: string, zone: string, index: number): { lat: number; lng: number } {
  const c = `${city} ${address}`.toLowerCase();
  // Mérida y alrededores
  if (c.includes('caucel')) return { lat: 20.995 + (index % 10) * 0.003, lng: -89.702 - (index % 8) * 0.002 };
  if (c.includes('kanasin') || c.includes('kanasín') || c.includes('mulchechen')) return { lat: 20.934 + (index % 8) * 0.003, lng: -89.562 + (index % 6) * 0.003 };
  if (c.includes('montejo')) return { lat: 21.025 + (index % 5) * 0.002, lng: -89.645 - (index % 4) * 0.002 };
  if (c.includes('altabrisa') || c.includes('diaz ordaz')) return { lat: 21.018 + (index % 4) * 0.002, lng: -89.585 + (index % 4) * 0.002 };
  if (c.includes('centro') && (c.includes('merida') || c.includes('mérida') || zone === 'Jaguar')) return { lat: 20.970 + (index % 12) * 0.002 - 0.01, lng: -89.623 + (index % 10) * 0.002 - 0.01 };
  if (c.includes('uman') || c.includes('umán')) return { lat: 20.882 + (index % 4) * 0.002, lng: -89.752 + (index % 3) * 0.002 };
  if (c.includes('conkal') || c.includes('xcuyun')) return { lat: 21.074 + (index % 3) * 0.002, lng: -89.521 + (index % 3) * 0.002 };
  if (c.includes('cholul')) return { lat: 21.041, lng: -89.553 };
  if (c.includes('chicxulub') || c.includes('progreso')) return { lat: 21.285 + (index % 4) * 0.003, lng: -89.664 + (index % 3) * 0.003 };
  if (c.includes('acanceh')) return { lat: 20.813, lng: -89.453 };
  if (c.includes('tixkokob')) return { lat: 20.999, lng: -89.395 };
  if (c.includes('timucuy')) return { lat: 20.811, lng: -89.514 };
  if (c.includes('motul')) return { lat: 21.096, lng: -89.283 };
  if (c.includes('ticul')) return { lat: 20.400, lng: -89.535 };
  if (c.includes('tekax')) return { lat: 20.203, lng: -89.288 };
  if (c.includes('sotuta')) return { lat: 20.596, lng: -89.006 };
  if (c.includes('huhi') || c.includes('huhí')) return { lat: 20.718, lng: -89.176 };
  if (c.includes('homun') || c.includes('homún')) return { lat: 20.738, lng: -89.285 };
  if (c.includes('ixil')) return { lat: 21.152, lng: -89.481 };
  if (c.includes('tizimin') || c.includes('tizimín')) return { lat: 21.143 + (index % 3) * 0.002, lng: -88.150 + (index % 3) * 0.002 };
  if (c.includes('valladolid')) return { lat: 20.690 + (index % 6) * 0.003, lng: -88.201 + (index % 5) * 0.002 };
  if (c.includes('piste') || c.includes('pisté')) return { lat: 20.699, lng: -88.590 };
  if (c.includes('espita')) return { lat: 21.011, lng: -88.307 };

  // Quintana Roo
  if (c.includes('cancun') || c.includes('cancún')) return { lat: 21.161 + (index % 8) * 0.004, lng: -86.848 + (index % 7) * 0.004 };
  if (c.includes('playa del carmen')) return { lat: 20.631 + (index % 8) * 0.003, lng: -87.078 + (index % 6) * 0.003 };
  if (c.includes('tulum')) return { lat: 20.211 + (index % 4) * 0.002, lng: -87.465 + (index % 3) * 0.002 };
  if (c.includes('cozumel')) return { lat: 20.508 + (index % 3) * 0.002, lng: -86.945 + (index % 3) * 0.002 };
  if (c.includes('chetumal')) return { lat: 18.513 + (index % 6) * 0.003, lng: -88.303 + (index % 5) * 0.003 };
  if (c.includes('felipe carrillo puerto')) return { lat: 19.578 + (index % 3) * 0.002, lng: -88.045 + (index % 3) * 0.002 };

  // Campeche
  if (c.includes('carmen')) return { lat: 18.643 + (index % 8) * 0.003, lng: -91.828 + (index % 7) * 0.003 };
  if (c.includes('campeche')) return { lat: 19.845 + (index % 5) * 0.003, lng: -90.536 + (index % 4) * 0.003 };
  if (c.includes('champoton') || c.includes('champotón')) return { lat: 19.351, lng: -90.722 };

  // La Laguna (Torreón, Gómez Palacio, Lerdo)
  if (c.includes('lerdo')) return { lat: 25.539, lng: -103.525 };
  if (c.includes('gomez palacio') || c.includes('gómez palacio')) return { lat: 25.568, lng: -103.498 };
  if (c.includes('torreon') || c.includes('torreón')) return { lat: 25.543 + (index % 5) * 0.003, lng: -103.418 + (index % 4) * 0.003 };
  if (c.includes('matamoros')) return { lat: 25.526, lng: -103.232 };

  // Zona Centro (Edo Mex, Morelos, CDMX, Veracruz)
  if (c.includes('malinalco')) return { lat: 18.948, lng: -99.497 };
  if (c.includes('tenango')) return { lat: 19.104, lng: -99.589 };
  if (c.includes('toluca')) return { lat: 19.282 + (index % 3) * 0.003, lng: -99.655 + (index % 3) * 0.003 };
  if (c.includes('miacatlan') || c.includes('miacatlán')) return { lat: 18.771, lng: -99.360 };
  if (c.includes('poza rica')) return { lat: 20.533, lng: -97.458 };
  if (c.includes('ciudad de mexico') || c.includes('cdmx')) return { lat: 19.432, lng: -99.133 };

  // Default según zona
  if (zone === 'Jaguar') return { lat: 20.970 + (index % 10) * 0.005, lng: -89.620 + (index % 8) * 0.005 };
  if (zone === 'Tiburón') return { lat: 20.630 + (index % 10) * 0.005, lng: -87.080 + (index % 8) * 0.005 };
  if (zone === 'Delfín') return { lat: 18.640 + (index % 8) * 0.004, lng: -91.820 + (index % 6) * 0.004 };
  if (zone === 'Águila') return { lat: 25.540 + (index % 6) * 0.004, lng: -103.420 + (index % 5) * 0.004 };
  if (zone === 'Colibrí') return { lat: 19.280 + (index % 6) * 0.004, lng: -99.650 + (index % 5) * 0.004 };

  return { lat: 20.9701, lng: -89.6231 };
}

